export type StorageDriver = 'local' | 's3';

export interface StorageProvider {
	put(key: string, data: Buffer, contentType: string): Promise<void>;
	get(key: string): Promise<Buffer | null>;
}

import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve, sep } from 'node:path';

import type { StorageProvider } from './types';

export class LocalStorageProvider implements StorageProvider {
	private readonly basePath: string;

	constructor(basePath: string) {
		this.basePath = resolve(basePath);
	}

	async put(key: string, data: Buffer): Promise<void> {
		const filePath = this.resolvePath(key);
		await mkdir(dirname(filePath), { recursive: true });
		await writeFile(filePath, data);
	}

	async get(key: string): Promise<Buffer | null> {
		try {
			return await readFile(this.resolvePath(key));
		} catch {
			return null;
		}
	}

	private resolvePath(key: string): string {
		const filePath = resolve(this.basePath, key);
		if (!filePath.startsWith(this.basePath + sep)) {
			throw new Error(`Storage key escapes the storage directory: ${key}`);
		}
		return filePath;
	}
}

import { GetObjectCommand, PutObjectCommand, S3Client } from '@aws-sdk/client-s3';

import type { StorageProvider } from './types';

export interface S3StorageOptions {
	bucket: string;
	region?: string;
	endpoint?: string;
	accessKeyId?: string;
	secretAccessKey?: string;
	forcePathStyle?: boolean;
	prefix?: string;
}

export class S3StorageProvider implements StorageProvider {
	private readonly client: S3Client;
	private readonly bucket: string;
	private readonly prefix: string;

	constructor(opts: S3StorageOptions) {
		this.bucket = opts.bucket;
		this.prefix = opts.prefix?.replace(/\/+$/, '') ?? '';
		this.client = new S3Client({
			region: opts.region ?? 'us-east-1',
			...(opts.endpoint && { endpoint: opts.endpoint }),
			...(opts.forcePathStyle && { forcePathStyle: true }),
			...(opts.accessKeyId &&
				opts.secretAccessKey && {
					credentials: { accessKeyId: opts.accessKeyId, secretAccessKey: opts.secretAccessKey },
				}),
		});
	}

	async put(key: string, data: Buffer, contentType: string): Promise<void> {
		await this.client.send(
			new PutObjectCommand({
				Bucket: this.bucket,
				Key: this.resolveKey(key),
				Body: data,
				ContentType: contentType,
			}),
		);
	}

	async get(key: string): Promise<Buffer | null> {
		try {
			const response = await this.client.send(
				new GetObjectCommand({ Bucket: this.bucket, Key: this.resolveKey(key) }),
			);
			const bytes = await response.Body?.transformToByteArray();
			return bytes ? Buffer.from(bytes) : null;
		} catch (error) {
			if (isMissingObjectError(error)) {
				return null;
			}
			throw error;
		}
	}

	private resolveKey(key: string): string {
		return this.prefix ? `${this.prefix}/${key}` : key;
	}
}

function isMissingObjectError(error: unknown): boolean {
	const name = (error as { name?: string } | null)?.name;
	return name === 'NoSuchKey' || name === 'NotFound';
}

import { env } from '../env';
import { logger } from '../utils/logger';
import { LocalStorageProvider } from './local';
import { S3StorageProvider } from './s3';
import type { StorageProvider } from './types';

export type { StorageDriver, StorageProvider } from './types';

let provider: StorageProvider | undefined;

/** Blob store for user-uploaded files, resolved from the STORAGE_* env vars on first use. */
export const getStorage = (): StorageProvider => {
	provider ??= createStorageProvider();
	return provider;
};

function createStorageProvider(): StorageProvider {
	if (env.STORAGE_DRIVER === 's3') {
		if (!env.STORAGE_S3_BUCKET) {
			throw new Error('STORAGE_S3_BUCKET is required when STORAGE_DRIVER=s3');
		}
		logger.info(`File storage: s3 (bucket=${env.STORAGE_S3_BUCKET})`, { source: 'system' });
		return new S3StorageProvider({
			bucket: env.STORAGE_S3_BUCKET,
			region: env.STORAGE_S3_REGION,
			endpoint: env.STORAGE_S3_ENDPOINT,
			accessKeyId: env.STORAGE_S3_ACCESS_KEY_ID,
			secretAccessKey: env.STORAGE_S3_SECRET_ACCESS_KEY,
			forcePathStyle: env.STORAGE_S3_FORCE_PATH_STYLE,
			prefix: env.STORAGE_S3_PREFIX,
		});
	}

	logger.info(`File storage: local (path=${env.STORAGE_LOCAL_PATH})`, { source: 'system' });
	return new LocalStorageProvider(env.STORAGE_LOCAL_PATH);
}

