import crypto from 'node:crypto';

import { and, eq, isNotNull, isNull } from 'drizzle-orm';

import s from '../db/abstractSchema';
import { db } from '../db/db';
import { getStorage } from '../storage';

export interface FileUpload {
	mediaType: string;
	data: string;
	filename?: string;
}

export interface SavedFile {
	id: string;
	mediaType: string;
	filename?: string;
}

export interface ChatFile {
	id: string;
	mediaType: string;
	filename: string | null;
	data: Buffer;
}

/** Writes the contents to the blob storage first so a failed upload never leaves an unreadable file behind. */
export const saveFiles = async (files: FileUpload[]): Promise<SavedFile[]> => {
	if (files.length === 0) {
		return [];
	}

	const saved = files.map((file) => ({
		id: crypto.randomUUID(),
		mediaType: file.mediaType,
		filename: file.filename,
	}));

	await Promise.all(
		files.map((file, index) =>
			getStorage().put(saved[index].id, Buffer.from(file.data, 'base64'), file.mediaType),
		),
	);
	await db
		.insert(s.messageImage)
		.values(saved.map(({ id, mediaType }) => ({ id, mediaType })))
		.execute();

	return saved;
};

export const getFileById = async (id: string): Promise<{ data: Buffer; mediaType: string } | undefined> => {
	const [row] = await db
		.select({ data: s.messageImage.data, mediaType: s.messageImage.mediaType })
		.from(s.messageImage)
		.where(eq(s.messageImage.id, id))
		.execute();

	if (!row) {
		return undefined;
	}

	const data = await readFileContent(id, row.data);
	return data ? { data, mediaType: row.mediaType } : undefined;
};

/** Every file uploaded in a chat, so tools can hand them over to the agent. */
export const getChatFiles = async (chatId: string): Promise<ChatFile[]> => {
	const rows = await db
		.select({
			id: s.messageImage.id,
			mediaType: s.messageImage.mediaType,
			filename: s.messagePart.filename,
			data: s.messageImage.data,
		})
		.from(s.messagePart)
		.innerJoin(s.chatMessage, eq(s.messagePart.messageId, s.chatMessage.id))
		.innerJoin(s.messageImage, eq(s.messagePart.imageId, s.messageImage.id))
		.where(
			and(eq(s.chatMessage.chatId, chatId), isNotNull(s.messagePart.imageId), isNull(s.chatMessage.supersededAt)),
		)
		.execute();

	const files = await Promise.all(
		rows.map(async (row) => {
			const data = await readFileContent(row.id, row.data);
			return data ? { ...row, data } : undefined;
		}),
	);

	return files.filter((file) => file !== undefined);
};

/** Files uploaded before the storage layer existed still carry their payload in the database. */
async function readFileContent(id: string, legacyData: string | null): Promise<Buffer | null> {
	if (legacyData) {
		return Buffer.from(legacyData, 'base64');
	}
	return getStorage().get(id);
}

const FILE_URL_PATTERN = /^\/i\/([a-f0-9-]+)$/;

export const buildFileUrl = (fileId: string): string => `/i/${fileId}`;

export const parseFileUrl = (url: string): string | null => url.match(FILE_URL_PATTERN)?.[1] ?? null;

