import { ALLOWED_FILE_MEDIA_TYPES, FILE_EXTENSIONS_BY_MEDIA_TYPE } from '@nao/shared/types';
import type { UIMessage } from '@nao/backend/chat';
import type { FileMediaType, FileUploadData } from '@nao/shared/types';
import type { SendMessageArgs } from '@/hooks/use-agent';

export function lastUserMessagePayload(messages: UIMessage[]): SendMessageArgs | null {
	for (let i = messages.length - 1; i >= 0; i--) {
		const message = messages[i];
		if (message.role !== 'user') {
			continue;
		}
		const text = message.parts
			.filter((part) => part.type === 'text')
			.map((part) => (part as { text: string }).text)
			.join('\n')
			.trim();
		const files = message.parts.map(fileFromFilePart).filter((file): file is FileUploadData => !!file);
		if (!text && files.length === 0) {
			return null;
		}
		return {
			text,
			...(files.length > 0 && { files }),
			...(message.citation && { citation: message.citation }),
		};
	}
	return null;
}

function fileFromFilePart(part: UIMessage['parts'][number]): FileUploadData | null {
	if (part.type !== 'file') {
		return null;
	}
	const file = part as { mediaType?: string; url?: string; filename?: string };
	if (!file.url) {
		return null;
	}
	const match = file.url.match(/^data:([^;]+);base64,(.*)$/);
	const mediaType = file.mediaType ?? match?.[1];
	if (!match || !isFileMediaType(mediaType)) {
		return null;
	}
	return {
		mediaType,
		data: match[2],
		filename: file.filename ?? `attachment.${FILE_EXTENSIONS_BY_MEDIA_TYPE[mediaType]}`,
	};
}

function isFileMediaType(value: unknown): value is FileMediaType {
	return typeof value === 'string' && ALLOWED_FILE_MEDIA_TYPES.includes(value as FileMediaType);
}

